{
 "thought_process": {
  "detected_emotions": "Buồn bã, lo sợ",
  "detected_symptoms": [
   "Đau ngực",
   "Khó thở",
   "Tim đập nhanh"
  ],
  "trigger_nutrition": false,
  "reasoning": "Đau ngực, khó thở, tim đập rất nhanh không rõ lý do cần chuyên gia/người lớn hỗ trợ; không đưa lời khuyên dinh dưỡng."
 },
 "side_talk": "Mình rất coi trọng những gì bạn vừa kể, cả nỗi buồn lẫn cơn đau ngực và khó thở. Chuyện nhà đang khó khăn mà bạn vẫn lo cho bố mẹ, điều đó thật đáng quý. Nhưng những dấu hiệu ở ngực và tim cần được bác sĩ kiểm tra, nên bạn hãy nói ngay với thầy cô hoặc bố mẹ hôm nay, bố mẹ sẽ thấy sức khỏe của bạn quan trọng hơn mọi thứ. Nếu lúc này bạn đau nhiều hoặc thở không nổi thì hãy báo thầy cô ngay và gọi 115.",
 "nutritional_advice": ""
}

{
 "thought_process": {
  "detected_emotions": "Thất vọng, nản chí",
  "detected_symptoms": [
   "khó tập trung"
  ],
  "trigger_nutrition": true,
  "reasoning": "Có khó tập trung, giảm chú ý khớp dữ liệu omega-3 chuỗi dài; kích hoạt lời khuyên dinh dưỡng."
 },
 "side_talk": "Bỏ ra bao nhiêu công sức mà kết quả không như mong đợi thì nản và hụt hẫng là điều dễ hiểu. Một điểm C không nói lên bạn có hợp với đại học hay không, nó chỉ cho thấy môn này đang khó với bạn lúc này. Khi nhìn thấy điểm đó, trong đầu bạn đã hiện lên những suy nghĩ gì về bản thân?",
 "nutritional_advice": "Cá minh thái là nguồn omega-3 chuỗi dài (EPA, DHA), vốn có vai trò chống viêm và là thành phần màng tế bào não. Bạn có thể ăn cá minh thái chiên hoặc kho trong bữa cơm nhà, nhưng lượng omega-3 mà nghiên cứu dùng thường cao hơn một bữa ăn nên đừng kỳ vọng món này giúp tập trung ngay. Cá cũng có cholesterol nên ăn điều độ."
}

{
 "thought_process": {
  "detected_emotions": "Căng thẳng, day dứt",
  "detected_symptoms": [
   "tê tay chân như kiến bò"
  ],
  "trigger_nutrition": true,
  "reasoning": "Có tê bì, kim châm tay chân khớp dữ liệu vitamin B12; kích hoạt lời khuyên dinh dưỡng."
 },
 "side_talk": "Bạn chọn đối diện thay vì né tránh, và điều đó cần rất nhiều can đảm. Cuộc nói chuyện có thể không suôn sẻ ngay và cảm xúc có thể dâng cao, nhưng khi bạn tiếp cận bằng sự thấu hiểu thì đó là cơ hội để cả hai làm lành. Mình tin bạn có thể làm được.",
 "nutritional_advice": "Cá ngừ hộp ngâm nước và tim bò đều giàu vitamin B12, mà B12 góp phần tạo hồng cầu và giúp hệ thần kinh hoạt động bình thường. Bạn có thể ăn cá ngừ hộp ăn kèm cơm, còn tim bò chỉ nên ăn ít vì có nhiều cholesterol. Tay chân tê kéo dài thì bạn nhớ nói với bố mẹ để đi khám."
}

{
 "thought_process": {
  "detected_emotions": "Tuyệt vọng, tự ti",
  "detected_symptoms": [
   "nhịn ăn kéo dài"
  ],
  "trigger_nutrition": false,
  "reasoning": "Nhịn ăn kéo dài để tự phạt cần chuyên gia/người lớn hỗ trợ; không đưa lời khuyên dinh dưỡng."
 },
 "side_talk": "Có vẻ có rất nhiều nghi ngờ bản thân gắn với điểm F đó. Nếu một người bạn của bạn bị điểm F rồi nghĩ cả năm sẽ trượt, bạn sẽ nói gì với bạn ấy? Việc bạn bỏ ăn để tự phạt mình là điều mình rất coi trọng, nên bạn hãy nói với bố mẹ, thầy cô hoặc nhân viên tư vấn học đường, và đi khám bác sĩ sớm để được giúp.",
 "nutritional_advice": ""
}

{
 "thought_process": {
  "detected_emotions": "Xấu hổ, lo lắng",
  "detected_symptoms": [
   "nứt khóe miệng"
  ],
  "trigger_nutrition": true,
  "reasoning": "Có nứt khóe miệng khớp dữ liệu riboflavin; kích hoạt lời khuyên dinh dưỡng."
 },
 "side_talk": "Giữ một điểm thấp trong lòng vì xấu hổ không dễ chút nào, và việc bạn nói ra ở đây đã là một bước can đảm. Một bài điểm thấp chưa thể quyết định cả năm học của bạn đâu. Mình thử cùng nhìn lại nhé, bạn đang nghĩ gì về kết quả môn sử này, kể mình nghe một suy nghĩ cụ thể được không?",
 "nutritional_advice": "Trứng chim cút và hạnh nhân đều giàu riboflavin (vitamin B2), chất góp phần duy trì niêm mạc bình thường và chuyển hóa năng lượng. Bạn có thể ăn trứng cút trong bữa sáng hoặc cơm nhà, và dùng hạnh nhân làm bữa phụ. Trứng cút nhiều cholesterol còn hạnh nhân nhiều chất béo, nên ăn điều độ nhé."
}

